func (q *Queries) SchemaInstalled(ctx context.Context) (bool, error) {
	row := q.db.QueryRow(ctx, schemaInstalled)
	var installed bool
	err := row.Scan(&installed)
	return installed, err
}

const traceKeys = `-- name: TraceKeys :many
SELECT
    k.meta_key::TEXT AS meta_key,
    count(*) AS transfers
FROM
    pgledger_transfers_view t,
    jsonb_object_keys(CASE WHEN jsonb_typeof(t.metadata) = 'object' THEN t.metadata ELSE '{}'::JSONB END) k (meta_key)
WHERE k.meta_key ILIKE $1::TEXT
GROUP BY meta_key
ORDER BY transfers DESC, meta_key ASC
LIMIT $2::INTEGER
`

type TraceKeysParams struct {
	Pattern  string
	RowLimit int32
}

type TraceKeysRow struct {
	MetaKey   string
	Transfers int64
}

func (q *Queries) TraceKeys(ctx context.Context, arg TraceKeysParams) ([]TraceKeysRow, error) {
	rows, err := q.db.Query(ctx, traceKeys, arg.Pattern, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TraceKeysRow
	for rows.Next() {
		var i TraceKeysRow
		if err := rows.Scan(&i.MetaKey, &i.Transfers); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const traceValues = `-- name: TraceValues :many
SELECT
    (metadata ->> $1::TEXT)::TEXT AS meta_value,
    count(*) AS transfers,
    min(created_at)::TIMESTAMPTZ AS first_at,
    max(created_at)::TIMESTAMPTZ AS last_at
FROM pgledger_transfers_view
WHERE metadata ->> $1::TEXT ILIKE $2::TEXT
GROUP BY meta_value
ORDER BY last_at DESC
LIMIT $3::INTEGER
`

type TraceValuesParams struct {
	MetaKey  string
	Pattern  string
	RowLimit int32
}

type TraceValuesRow struct {
	MetaValue string
	Transfers int64
	FirstAt   time.Time
	LastAt    time.Time
}

func (q *Queries) TraceValues(ctx context.Context, arg TraceValuesParams) ([]TraceValuesRow, error) {
	rows, err := q.db.Query(ctx, traceValues, arg.MetaKey, arg.Pattern, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TraceValuesRow
	for rows.Next() {
		var i TraceValuesRow
		if err := rows.Scan(
			&i.MetaValue,
			&i.Transfers,
			&i.FirstAt,
			&i.LastAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
